function load() { try { const o = JSON.parse(localStorage.getItem(SAVE)); if (!o || !o.mhp) return null; const p = { ...newP(), ...o }; if (!o.v) { p.v = 2; p.db = (p.lv - 1) * 2; p.gold += p.xp || 0; p.xp = 0; p.pot = Math.max(p.pot, 3); p.fires = {}; for (let i = 0; i <= Math.min(2, p.fire); i++) p.fires[i] = 1; p.fires[0] = 1; } return p; } catch (_) { return null; } }
