function start(fresh) { P = fresh ? newP() : load() || newP(); R = newR(); if (!fresh) { const f = FIRES[P.fire] || FIRES[0]; if (P.q > 0) { P.x = f[0] - 50; P.y = f[1] + 40; } } spawnAll(); PICK = []; FX = []; CAM.x = P.x; CAM.y = P.y; CAM.z = 1; R.st = P.mst; REG = regionOf(P.x, P.y); ST = 'play'; if (fresh) { save(); cine([{ x: 2100, y: 900, T: 4.2, cap: 'A völgyet egykor az Ősforrás éltette, és a Zsiliprend lovagjai vigyáztak minden cseppjére.' }, { x: 2100, y: 1700, T: 4.2, cap: 'Aztán eljött a Nagy Ár éjszakája – és utána a Hosszú Nyár, amely azóta sem ért véget.' }, { x: 1300, y: 1960, T: 4.4, cap: 'Akit a folyó egyszer elragad, azt nem adja vissza. Téged visszaadott.' }], () => banner('HAJNALRÉV', 'Partravetett vagy. Valaki vár a faluban.')); } }
